import verifiers as vf
from datasets import Dataset

def exact_match(completion, answer, info, **kwargs):
    return 1.0 if completion == answer else 0.0

def contains_answer(completion, answer, info, **kwargs):
    return 1.0 if answer in completion else 0.0

def brevity(completion, answer, info, **kwargs):
    return 1.0 if len(completion) < 24 else 0.0

def length_chars(completion, answer, info, **kwargs):
    return float(len(completion))

def load_environment(**kwargs):
    rubric = vf.Rubric(funcs=[exact_match, contains_answer, brevity, length_chars], weights=[0.6, 0.25, 0.15, 0.0])
    dataset = Dataset.from_list([{"question": "stub", "answer": "stub"}])
    return vf.SingleTurnEnv(dataset=dataset, rubric=rubric, **kwargs)

